//! A small library demonstrating type-safe bitflags.
//!
//! The [`Flags`] type is generated by the [`bitflags`] crate, so its values
//! are ordinary constants that compose with the bitwise operators and expose
//! safe queries like [`Flags::contains`] and [`Flags::intersects`]. Because it
//! is a distinct type, unrelated integers and flag sets cannot be mixed in by
//! accident.

use bitflags::bitflags;

bitflags! {
    /// A set of access flags that can be combined and checked.
    ///
    /// Combine flags with `|` and test them with [`Flags::contains`]:
    ///
    /// ```
    /// use flags::Flags;
    ///
    /// let mut perms = Flags::READ | Flags::WRITE;
    /// assert!(perms.contains(Flags::READ));
    ///
    /// perms.insert(Flags::EXEC);
    /// assert!(perms.contains(Flags::READ | Flags::WRITE | Flags::EXEC));
    /// ```
    #[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
    pub struct Flags: u32 {
        /// Read access.
        const READ  = 0b0000_0001;
        /// Write access.
        const WRITE = 0b0000_0010;
        /// Execute access.
        const EXEC  = 0b0000_0100;
    }
}

impl Flags {
    /// Returns `true` if every flag set in `other` is also set in `self`.
    pub fn has(self, other: Flags) -> bool {
        self.contains(other)
    }

    /// Returns `true` if any flag set in `other` is also set in `self`.
    pub fn includes_any(self, other: Flags) -> bool {
        self.intersects(other)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn constants_have_distinct_bits() {
        assert!(Flags::READ.contains(Flags::READ));
        assert!(!Flags::READ.contains(Flags::WRITE));
        assert!(!Flags::WRITE.contains(Flags::EXEC));
    }

    #[test]
    fn flags_can_be_combined() {
        let rw = Flags::READ | Flags::WRITE;
        assert_eq!(rw.bits(), Flags::READ.bits() | Flags::WRITE.bits());
        assert!(rw.contains(Flags::READ));
        assert!(rw.contains(Flags::WRITE));
        assert!(!rw.contains(Flags::EXEC));
    }

    #[test]
    fn queries_distinguish_contains_from_intersects() {
        let rw = Flags::READ | Flags::WRITE;
        let wx = Flags::WRITE | Flags::EXEC;

        assert!(rw.has(Flags::READ));
        assert!(!rw.has(wx));
        assert!(rw.includes_any(wx));
        assert!(!rw.intersects(Flags::EXEC));
    }

    #[test]
    fn empty_and_all_boundaries() {
        assert_eq!(Flags::empty().bits(), 0);
        assert!(Flags::all().contains(Flags::READ | Flags::WRITE | Flags::EXEC));
        assert!(!Flags::empty().contains(Flags::READ));
    }

    #[test]
    fn set_operations() {
        let mut perms = Flags::READ;
        perms.insert(Flags::WRITE);
        assert_eq!(perms, Flags::READ | Flags::WRITE);

        perms.remove(Flags::READ);
        assert_eq!(perms, Flags::WRITE);

        perms.toggle(Flags::EXEC);
        assert_eq!(perms, Flags::WRITE | Flags::EXEC);
    }
}

